async function readAllSheets(spec) {
  const abs = path.join(root, spec.rel);
  const raw = await fs.readFile(abs);
  const actualSha = sha256Buffer(raw);
  const baselineRow = baselineByPath.get(spec.rel);
  if (!baselineRow) throw new Error(`STOP_CONDITION: input absent from start baseline: ${spec.rel}`);
  if (baselineRow.sha256 !== actualSha) {
    throw new Error(`STOP_CONDITION: input changed after baseline: ${spec.rel}`);
  }
  const workbook = await SpreadsheetFile.importXlsx(await FileBlob.load(abs));
  const names = spec.sheets ?? (
    await workbook.inspect({ kind: "sheet", include: "id,name", maxChars: 30000 })
  ).ndjson
    .trim()
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line).name);
  const sheets = [];
  for (const sheetSpec of names) {
    const name = typeof sheetSpec === "string" ? sheetSpec : sheetSpec.name;
    const sheet = workbook.worksheets.getItem(name);
    const used =
      typeof sheetSpec === "string" || !sheetSpec.range
        ? sheet.getUsedRange(true)
        : sheet.getRange(sheetSpec.range);
    sheets.push({
      name,
      address: used?.address ?? "A1",
      values: used?.values ?? [],
      formulas: used?.formulas ?? [],
    });
  }
  return {
    role: spec.role,
    path: abs,
    relative_path: spec.rel,
    file_name: path.basename(abs),
    size_bytes: raw.byteLength,
    sha256: actualSha,
    sheets,
  };

