def build_models() -> dict[str, Any]:
    p04 = OUTPUT_ROOT / "04_字段标准化与时间统一"
    p05 = OUTPUT_ROOT / "05_交易事件与仓位链重建"
    p06 = OUTPUT_ROOT / "06_人工复盘匹配"

    futures = read_table(
        p04 / "标准化数据/04_合约交易流水_标准化.xlsx", "标准化数据"
    )
