        p04 / "标准化数据/04_全账户交易流水_标准化.xlsx", "标准化数据"
    )
    screenshot_index = read_table(
        p04 / "标准化数据/04_账户截图索引_标准化.xlsx", "标准化数据"
    )
    snapshot_confirmations, snapshot_confirmation_payload = (
        load_snapshot_confirmations()
    )
    cycles = read_table(
        p06 / "匹配结果/06_真实仓位周期覆盖表.xlsx", "周期覆盖"
    )
    funding_candidates = read_table(
        p05 / "对账与验证/05_资金费候选关联结果.xlsx", "资金费候选"
    )
    ledger_association = read_table(
        p05 / "对账与验证/05_合约资金事件关联状态.xlsx", "逐事件行"
    )
    pnl_scope = read_table(
        p06 / "差异与复核/06_盈亏口径差异清单.xlsx", "盈亏口径"
    )
    b01_transfers = read_table(
        p04 / "补充标准化数据_B01/04_跟单转账记录_标准化_B01.xlsx",
        "重建数据",
