        p05 / "补充证据_B01/05_跟单项目清单_B01.xlsx", "项目生命周期"
    )

    if len(futures) != 21452 or len(account) != 21614:
        raise RuntimeError(
            f"资金输入数量不符：合约{len(futures)}，全账户{len(account)}"
        )
    if len(cycles) != 148 or len(screenshot_index) != 38:
        raise RuntimeError(
            f"阶段07控制数量不符：周期{len(cycles)}，截图{len(screenshot_index)}"
        )

    cycle_by_id = {str(row["position_cycle_id"]): row for row in cycles}
    cycle_origin = {
        str(row["position_cycle_id"]): str(row.get("trading_origin") or "")
        for row in cycles
    }
    association_by_source = {
        str(row["source_event_record_id"]): row for row in ledger_association
    }

