const mappingRows = table("M0正式148周期映射", "148周期统一映射");
const activeMappings = mappingRows
  .filter((row) => row["交易来源分类"] === "个人主动")
  .sort((a, b) => String(a["新人工复盘编号"]).localeCompare(String(b["新人工复盘编号"])));
const copyMappings = mappingRows.filter((row) => row["交易来源分类"] === "自动跟单");
assert(mappingRows.length === 148, `mapping row count ${mappingRows.length}`);
assert(activeMappings.length === 136 && copyMappings.length === 12, `active/copy ${activeMappings.length}/${copyMappings.length}`);
const expectedTs = Array.from({ length: 136 }, (_, index) => `T${String(index + 1).padStart(3, "0")}`);
assert(
  activeMappings.every((row, index) => row["新人工复盘编号"] === expectedTs[index]),
  "new T numbering is not T001-T136",
);
assert(new Set(activeMappings.map((row) => row.position_cycle_id)).size === 136, "active position_cycle_id not unique");
assert(copyMappings.every((row) => !row["新人工复盘编号"]), "copy cycles unexpectedly have new T");

const cycleRows = table("M1现行148周期主表", "148周期主表");
assert(cycleRows.length === 148 && new Set(cycleRows.map((row) => row.position_cycle_id)).size === 148, "M1 cycle master mismatch");
const cycleById = new Map(cycleRows.map((row) => [row.position_cycle_id, row]));
const activeByCycle = new Map(activeMappings.map((row) => [row.position_cycle_id, row]));
const cycleFreeze = activeMappings.map((row) => {
  const cycle = cycleById.get(row.position_cycle_id);
  assert(cycle, `cycle missing from M1 master ${row.position_cycle_id}`);
  assert(cycle["交易来源分类"] === "个人主动", `cycle source mismatch ${row.position_cycle_id}`);
  const mappedDirection = row["方向"] === "多头" ? "LONG" : row["方向"] === "空头" ? "SHORT" : row["方向"];
  assert(cycle.symbol === row["品种"] && cycle.initial_direction === mappedDirection, `symbol/direction mismatch ${row.position_cycle_id}`);
  return {
    mapping_version: row.mapping_version,
    position_cycle_id: row.position_cycle_id,
    new_t_id: row["新人工复盘编号"],
    old_tu_id: row["旧技术展示编号"],
    old_manual_id: row["旧人工复盘编号"],
    symbol: row["品种"],
    direction: mappedDirection,
    direction_cn: row["方向"],
    source_class: row["交易来源分类"],
    personal_active: row["是否个人主动"],
    copy_trading: row["是否自动跟单"],
    cycle_start_utc: cycle.cycle_start_time_utc,
    cycle_end_utc: cycle.cycle_end_time_utc,
    expected_fill_count: number(cycle.total_fill_count),
    expected_order_count: number(cycle.order_count),
    mapping_source_sha256: input("M0正式148周期映射").sha256,
    cycle_master_sha256: input("M1现行148周期主表").sha256,
    freeze_status: "PASS",
  };
});

