const payload = JSON.parse(await fs.readFile(payloadPath, "utf8"));
const onlyArg = args.find((x) => x.startsWith("--only="));
const onlyTokens = onlyArg ? onlyArg.slice(7).split(",").filter(Boolean) : [];
const inheritOnly = args.includes("--inherit-only");
const selected = (itemPath) => !onlyTokens.length || onlyTokens.some((token) => itemPath.includes(token));
const supportDir = path.resolve(path.dirname(payloadPath), "..");
const previewDir = path.join(supportDir, "渲染预览");
const qaPath = path.join(supportDir, "基线与核验", "M1_artifact_tool构建QA.json");

function writeSheet(workbook, workbookPath, spec, sheetIndex, existingSheet = null) {
  const ws = existingSheet || workbook.worksheets.add(spec.name);
  ws.showGridLines = false;
  const columns = spec.columns || [];
  const colCount = Math.max(1, columns.length);
  const lastCol = colName(colCount - 1);
  const mergedLast = colName(Math.min(colCount, 12) - 1);
  ws.mergeCells(`A1:${mergedLast}1`);
  ws.getRange("A1").values = [[spec.title || spec.name]];
  ws.getRange(`A1:${mergedLast}1`).format = { fill: palette.navy, font: { bold: true, color: palette.white, size: 16 }, verticalAlignment: "center", rowHeight: 30 };
  ws.mergeCells(`A2:${mergedLast}2`);
  ws.getRange("A2").values = [[spec.subtitle || ""]];
  ws.getRange(`A2:${mergedLast}2`).format = { fill: palette.paleBlue, font: { color: palette.gray, italic: true, size: 10 }, verticalAlignment: "center", wrapText: true, rowHeight: 36 };
  ws.getRange(`A4:${lastCol}4`).values = [columns];
  ws.getRange(`A4:${lastCol}4`).format = { fill: palette.blue, font: { bold: true, color: palette.white }, horizontalAlignment: "center", verticalAlignment: "center", wrapText: true, rowHeight: 34, borders: { preset: "all", style: "thin", color: palette.border } };

  const dateSet = new Set(spec.date_columns || []);
  const rows = (spec.rows || []).map((row) => columns.map((header, i) => {
    const value = dateSet.has(header) ? asDate(row[i]) : (row[i] ?? null);
    return typeof value === "string" && value.startsWith("=") ? `'${value}` : value;
  }));
  const lastRow = 4 + rows.length;
  if (rows.length) {
    ws.getRange(`A5:${lastCol}${lastRow}`).values = rows;
    ws.getRange(`A5:${lastCol}${lastRow}`).format = { borders: { preset: "inside", style: "thin", color: palette.border }, verticalAlignment: "top", wrapText: true };
    const table = ws.tables.add(`A4:${lastCol}${lastRow}`, true, uniqueTableName(workbookPath, spec.name, sheetIndex));
    table.style = "TableStyleMedium2"; table.showBandedRows = true; table.showFilterButton = true;
    addStatusFormatting(ws, columns, 5, lastRow);
  }
  for (const [header, template] of Object.entries(spec.formula_columns || {})) {
    const index = columns.indexOf(header);
    if (index < 0) throw new Error(`formula column not found: ${header}`);
    const col = colName(index);
    for (let row = 5; row <= lastRow; row += 1) ws.getRange(`${col}${row}`).formulas = [[template.replaceAll("{row}", String(row))]];

const qa = { generated_at: new Date().toISOString(), payload: payloadPath, workbooks: [] };
const workbookSpecs = inheritOnly ? [] : (payload.workbooks || []).filter((spec) => selected(spec.path));
for (let wi = 0; wi < workbookSpecs.length; wi += 1) {
  const spec = workbookSpecs[wi];
  const wb = Workbook.create();
  const placeholders = spec.sheets.map((s) => wb.worksheets.add(s.name));
  const built = spec.sheets.map((s, si) => writeSheet(wb, spec.path, s, si, placeholders[si]));
  const result = await qaAndPreview(wb, spec.path, built);
  await fs.mkdir(path.dirname(spec.path), { recursive: true });
  const output = await SpreadsheetFile.exportXlsx(wb); await output.save(spec.path);
  qa.workbooks.push({ path: spec.path, sheets: spec.sheets.map((s) => s.name), ...result });

def clean(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, (np.bool_, bool)):
        return bool(value)
    if isinstance(value, (np.integer,)):
        return int(value)
    if isinstance(value, (np.floating, float)):
        return float(value) if math.isfinite(float(value)) else None
    if isinstance(value, (pd.Timestamp, datetime)):
        return value.isoformat(sep=" ")
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    text = str(value)
    return text if len(text) <= 32000 else text[:31990] + "…"

def records(df: pd.DataFrame, columns: list[str]) -> list[list[Any]]:
    return [[clean(v) for v in row] for row in df[columns].itertuples(index=False, name=None)]

payload_path = Path(sys.argv[1]).resolve()
payload = json.loads(payload_path.read_text(encoding="utf-8"))
changed = []
for workbook in payload["workbooks"]:
    name = Path(workbook["path"]).name
    for sheet in workbook["sheets"]:
        for row in sheet.get("rows", []):
            for index, value in enumerate(row):
                if isinstance(value, (dict, list)):
                    row[index] = json.dumps(value, ensure_ascii=False, sort_keys=True)
                    changed.append(name)
        if name in {"00_V2阶段执行状态表.xlsx", "M1_02_阶段00-09迁移计划与执行状态.xlsx"}:
            columns = sheet.get("columns", [])
            if "当前状态" in columns:
                index = columns.index("当前状态")
            elif "状态" in columns:
                index = columns.index("状态")
            else:
                continue
            for row in sheet.get("rows", []):
                row[index] = "已完成"
            changed.append(name)
payload_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")

