  const mergedLast = colName(Math.min(colCount, 12) - 1);
  ws.mergeCells(`A1:${mergedLast}1`);
  ws.getRange("A1").values = [[spec.title || spec.name]];
  ws.getRange(`A1:${mergedLast}1`).format = { fill: palette.navy, font: { bold: true, color: palette.white, size: 16 }, verticalAlignment: "center", rowHeight: 30 };
  ws.mergeCells(`A2:${mergedLast}2`);
  ws.getRange("A2").values = [[spec.subtitle || ""]];
  ws.getRange(`A2:${mergedLast}2`).format = { fill: palette.paleBlue, font: { color: palette.gray, italic: true, size: 10 }, verticalAlignment: "center", wrapText: true, rowHeight: 36 };
  ws.getRange(`A4:${lastCol}4`).values = [columns];
  ws.getRange(`A4:${lastCol}4`).format = { fill: palette.blue, font: { bold: true, color: palette.white }, horizontalAlignment: "center", verticalAlignment: "center", wrapText: true, rowHeight: 34, borders: { preset: "all", style: "thin", color: palette.border } };

  const dateSet = new Set(spec.date_columns || []);
  const rows = (spec.rows || []).map((row) => columns.map((header, i) => {
    const value = dateSet.has(header) ? asDate(row[i]) : (row[i] ?? null);
    return typeof value === "string" && value.startsWith("=") ? `'${value}` : value;
  }));
  const lastRow = 4 + rows.length;
  if (rows.length) {
    ws.getRange(`A5:${lastCol}${lastRow}`).values = rows;
    ws.getRange(`A5:${lastCol}${lastRow}`).format = { borders: { preset: "inside", style: "thin", color: palette.border }, verticalAlignment: "top", wrapText: true };
