) -> tuple[list[dict[str, Any]], dict[str, dict[str, Any]]]:
    groups: collections.defaultdict[tuple[str, str], list[Mapping[str, Any]]] = (
        collections.defaultdict(list)
    )
    for fill in fills:
        fill_id = text(fill.get("standard_record_id"))
        fill_segments = segments_by_fill[fill_id]
        partition = fill_segments[0]["partition_key"]
        groups[(partition, text(fill.get("fill_time_utc")) or "")].append(fill)
    audit_rows: list[dict[str, Any]] = []
    fill_metadata: dict[str, dict[str, Any]] = {}
    for (partition, event_time), group in sorted(
        groups.items(), key=lambda item: (item[0][0], item[0][1])
    ):
        ordered = sorted(group, key=source_sort_key)
        if len(ordered) == 1:
            fill_id = text(ordered[0].get("standard_record_id"))
            fill_metadata[fill_id] = {
                "same_second_group_id": None,
                "same_second_group_size": 1,
                "deterministic_sort_rank": 1,
                "same_second_order_sensitive": "否",
            }
            continue
        group_id = stable_id("S05-SS", partition, event_time)
        signed_signs: set[int] = set()
        zero_crossing = False
        for rank, fill in enumerate(ordered, 1):
