        require(removal_ids, f"摘要异常未识别到需隔离Order：{summary['summary_id']}")
        retained_assignments = []
        for fill, action, basis in summary["assignments"]:
            order_id = text(fill.get("order_id")) or ""
            if order_id in removal_ids:
                fill_id = text(fill.get("standard_record_id"))
                annotations[fill_id].update(
                    {
                        "assigned_summary_id": None,
                        "summary_action": None,
                        "assignment_basis": (
                            "摘要数量守恒唯一Order子集隔离；不属于该普通摘要仓位路径"
                        ),
                    }
                )
                removed_fills.append(dict(fill))
            else:
                retained_assignments.append((fill, action, basis))
        summary["assignments"] = retained_assignments
        summary["removed_order_ids"] = sorted(removal_ids, key=numeric_sort_key)
        recalculated = calculate_summary_path(summary)
        require(
            recalculated["ending_position"] == 0
            and recalculated["minimum_position"] >= 0
            and recalculated["opening_quantity"] == summary["closed_quantity"]
