        canonical_commission = decimal_value(
            cycle["canonical_commission"], allow_none=False
        )
        ledger_commission = commission_by_cycle[cycle_id]
        commission_difference = ledger_commission - canonical_commission
        cycle["futures_ledger_commission_direct_sum"] = decimal_text(
            ledger_commission
        )
        cycle["commission_reconciliation_difference"] = decimal_text(
            commission_difference
        )
        cycle["commission_reconciliation_status"] = (
            "EXACT_MATCH_NO_DOUBLE_COUNT"
            if commission_difference == 0
            else "PARTIAL_LEDGER_COVERAGE_CANONICAL_FILL_RETAINED"
        )
        cycle["commission_ledger_matched_fill_count"] = commission_match_counts[
            cycle_id
        ]
        cycle["cycle_fill_count_for_fee_control"] = fill_counts[cycle_id]

