def assign_fills_to_summaries(
    fills: Sequence[Mapping[str, Any]],
    summaries: list[dict[str, Any]],
) -> tuple[dict[str, dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    order_pnl: collections.defaultdict[str, Decimal] = collections.defaultdict(Decimal)
    for fill in fills:
        order_pnl[text(fill.get("order_id")) or ""] += decimal_value(
            fill.get("realized_pnl"), allow_none=False
        )
    annotations: dict[str, dict[str, Any]] = {}
    unresolved_candidates: list[dict[str, Any]] = []

    for fill in fills:
        fill_id = text(fill.get("standard_record_id"))
        fill_time = parse_time(fill.get("fill_time_utc"))
        symbol = text(fill.get("symbol_standard"))
        candidates: list[tuple[dict[str, Any], str]] = []
        for summary in summaries:
            if summary["symbol"] != symbol:
                continue
            if summary["open_time"] <= fill_time <= summary["close_time"]:
                candidates.append((summary, summary_action(summary, fill)))
        chosen: tuple[dict[str, Any], str] | None = None
        basis = "NO_SUMMARY_INTERVAL_CANDIDATE"
        if len(candidates) == 1:
            chosen = candidates[0]
            basis = "唯一symbol+摘要时间区间候选"
        elif (
            len(candidates) == 2
            and {action for _, action in candidates} == {"OPEN", "CLOSE"}
        ):
            target_action = (
                "CLOSE"
                if order_pnl[text(fill.get("order_id")) or ""] != 0
                else "OPEN"
            )
            matching = [
                candidate
                for candidate in candidates
                if candidate[1] == target_action
            ]
            if len(matching) == 1:
                chosen = matching[0]
                basis = (
                    "同symbol多空摘要重叠；Order已实现盈亏"
                    + ("非0选择减仓侧" if target_action == "CLOSE" else "为0选择增仓侧")
                )
        if chosen is not None:
            summary, action = chosen
            summary["assignments"].append((fill, action, basis))
            annotations[fill_id] = {
                "summary_candidate_count": len(candidates),
                "assigned_summary_id": summary["summary_id"],
                "summary_action": action,
                "assignment_basis": basis,
            }
        else:
            annotations[fill_id] = {
                "summary_candidate_count": len(candidates),
                "assigned_summary_id": None,
                "summary_action": None,
                "assignment_basis": basis,
            }
            if candidates:
                unresolved_candidates.append(
                    {
                        "fill_record_id": fill_id,
                        "trade_id": text(fill.get("trade_id")),
                        "order_id": text(fill.get("order_id")),
                        "symbol": symbol,
                        "fill_time_utc": text(fill.get("fill_time_utc")),
                        "candidate_summary_ids": "|".join(
                            candidate["summary_id"] for candidate, _ in candidates
                        ),
                        "candidate_actions": "|".join(
                            action for _, action in candidates
                        ),
                        "status": "UNRESOLVED",
                    }
                )
    require(
        not unresolved_candidates,
        f"摘要区间候选无法自动消解：{len(unresolved_candidates)}条",
    )

    removed_fills: list[dict[str, Any]] = []
    remediation_rows: list[dict[str, Any]] = []
    for summary in summaries:
        calculated = calculate_summary_path(summary)
        opening_excess = calculated["opening_quantity"] - summary["closed_quantity"]
        closing_excess = calculated["closing_quantity"] - summary["closed_quantity"]
        if opening_excess == 0 and closing_excess == 0:
            continue
        require(
            opening_excess >= 0 and closing_excess >= 0,
            f"摘要数量不足而非额外Fill：{summary['summary_id']}",
        )
        grouped: dict[str, dict[str, Any]] = {}
        for fill, action, basis in summary["assignments"]:
            order_id = text(fill.get("order_id")) or ""
            group = grouped.setdefault(
                order_id,
                {"action": action, "quantity": Decimal(0), "fills": [], "basis": basis},
            )
            require(group["action"] == action, f"同一Order跨摘要作用冲突：{order_id}")
            group["quantity"] += decimal_value(
                fill.get("fill_quantity"), allow_none=False
            )
            group["fills"].append(fill)
        open_orders = {
            order_id: group["quantity"]
            for order_id, group in grouped.items()
            if group["action"] == "OPEN"
        }
        close_orders = {
            order_id: group["quantity"]
            for order_id, group in grouped.items()
            if group["action"] == "CLOSE"
        }
        open_subset, open_status = find_unique_order_subset(open_orders, opening_excess)
        close_subset, close_status = find_unique_order_subset(close_orders, closing_excess)
        require(
            open_subset is not None
            and close_subset is not None
            and open_status in {"NOT_NEEDED", "UNIQUE"}
            and close_status in {"NOT_NEEDED", "UNIQUE"},
            f"无法唯一识别摘要外账户范围Order：{summary['summary_id']}",
        )
        removal_ids = set(open_subset) | set(close_subset)
        require(removal_ids, f"摘要异常未识别到需隔离Order：{summary['summary_id']}")
        retained_assignments = []
        for fill, action, basis in summary["assignments"]:
            order_id = text(fill.get("order_id")) or ""
            if order_id in removal_ids:
                fill_id = text(fill.get("standard_record_id"))
                annotations[fill_id].update(
                    {
                        "assigned_summary_id": None,
                        "summary_action": None,
                        "assignment_basis": (
                            "摘要数量守恒唯一Order子集隔离；不属于该普通摘要仓位路径"
                        ),
                    }
                )
                removed_fills.append(dict(fill))
            else:
                retained_assignments.append((fill, action, basis))
        summary["assignments"] = retained_assignments
        summary["removed_order_ids"] = sorted(removal_ids, key=numeric_sort_key)
        recalculated = calculate_summary_path(summary)
        require(
            recalculated["ending_position"] == 0
            and recalculated["minimum_position"] >= 0
            and recalculated["opening_quantity"] == summary["closed_quantity"]
            and recalculated["closing_quantity"] == summary["closed_quantity"]
            and recalculated["maximum_position"] == summary["maximum_quantity"],

def enrich_cycle_financial_reconciliation(
    cycles: list[dict[str, Any]],
    pnl_rows: Sequence[Mapping[str, Any]],
    commission_rows: Sequence[Mapping[str, Any]],
    fill_cycle_ids: Mapping[str, Sequence[str]],
) -> None:
    pnl_by_cycle: collections.defaultdict[str, Decimal] = collections.defaultdict(Decimal)
    commission_by_cycle: collections.defaultdict[str, Decimal] = (
        collections.defaultdict(Decimal)
    )
    commission_match_counts: collections.Counter[str] = collections.Counter()
    fill_counts: collections.Counter[str] = collections.Counter()
    for fill_id, cycle_ids in fill_cycle_ids.items():
        for cycle_id in cycle_ids:
            fill_counts[cycle_id] += 1
    for row in pnl_rows:
        if row["reconciliation_status"] != "EXACT_MATCH":
            continue
        for cycle_id in fill_cycle_ids.get(row["fill_record_id"], ()):
            pnl_by_cycle[cycle_id] += decimal_value(
                row["ledger_realized_pnl_amount"], allow_none=False
            )
    for row in commission_rows:
        if row["reconciliation_status"] != "EXACT_MATCH":
            continue
        for cycle_id in fill_cycle_ids.get(row["fill_record_id"], ()):
            commission_by_cycle[cycle_id] += decimal_value(
                row["ledger_commission_cost_absolute"], allow_none=False
            )
            commission_match_counts[cycle_id] += 1
    for cycle in cycles:
        cycle_id = cycle["position_cycle_id"]
        canonical_pnl = decimal_value(
            cycle["canonical_realized_pnl"], allow_none=False
        )
        ledger_pnl = pnl_by_cycle[cycle_id]
        pnl_difference = ledger_pnl - canonical_pnl
        require(pnl_difference == 0, f"周期已实现盈亏对账差异：{cycle_id}")
        cycle["futures_ledger_realized_pnl_direct_sum"] = decimal_text(ledger_pnl)
        cycle["realized_pnl_reconciliation_difference"] = decimal_text(
            pnl_difference
        )
        cycle["realized_pnl_reconciliation_status"] = "EXACT_MATCH_NO_DOUBLE_COUNT"
        canonical_commission = decimal_value(
            cycle["canonical_commission"], allow_none=False
        )
        ledger_commission = commission_by_cycle[cycle_id]
        commission_difference = ledger_commission - canonical_commission
        cycle["futures_ledger_commission_direct_sum"] = decimal_text(
            ledger_commission
        )
        cycle["commission_reconciliation_difference"] = decimal_text(
            commission_difference
        )
        cycle["commission_reconciliation_status"] = (
            "EXACT_MATCH_NO_DOUBLE_COUNT"
            if commission_difference == 0
            else "PARTIAL_LEDGER_COVERAGE_CANONICAL_FILL_RETAINED"
        )
        cycle["commission_ledger_matched_fill_count"] = commission_match_counts[
            cycle_id
        ]
        cycle["cycle_fill_count_for_fee_control"] = fill_counts[cycle_id]

