  const lines = readline.createInterface({ input, crlfDelay: Infinity });
  let chunk = [];
  let written = 0;
  for await (const line of lines) {
    if (!line.trim()) continue;
    chunk.push(JSON.parse(line));
    if (chunk.length >= DATA_CHUNK_ROWS) {
      written += await writeRows(sheet, 4 + written, chunk, columns, DATA_CHUNK_ROWS);
      chunk = [];
    }
  }
  if (chunk.length) {
    written += await writeRows(sheet, 4 + written, chunk, columns, DATA_CHUNK_ROWS);
  }
  return written;

