# 先以同品种的最小双边界差确定唯一锚点，再从实际差异分布导出时间容差。
nearest_pairs: list[
    tuple[dict[str, Any], dict[str, Any], float, float, float | None]
] = []
for manual in manuals:
    manual_symbol = f"{manual['manual_instrument_standard']}USDT"
    manual_open = parse_time(manual["manual_open_time_beijing"])
    manual_close = parse_time(manual["manual_close_time_beijing"])
    candidates: list[tuple[float, float, float, dict[str, Any]]] = []
    for cycle in cycles:
        if str(cycle.get("symbol")) != manual_symbol:
            continue
        open_abs = abs(
            (
                parse_time(cycle["cycle_start_time_beijing"]) - manual_open
            ).total_seconds()
        )
        close_abs = abs(
            (
                parse_time(cycle["cycle_end_time_beijing"]) - manual_close
            ).total_seconds()
        )
        candidates.append((open_abs + close_abs, open_abs, close_abs, cycle))
    if not candidates:
        raise RuntimeError(
            f"{manual['manual_review_trade_id']}不存在同品种真实周期候选"
        )
    candidates.sort(
        key=lambda item: (
            item[0],
            item[3]["cycle_start_time_utc"],
            item[3]["position_cycle_id"],
        )
    )
    nearest = candidates[0]
    runner_up = candidates[1][0] if len(candidates) > 1 else None
    nearest_pairs.append(
        (manual, nearest[3], nearest[1], nearest[2], runner_up)
    )
tolerance_seconds = int(
    max(max(open_abs, close_abs) for _, _, open_abs, close_abs, _ in nearest_pairs)
)
if tolerance_seconds != 59:
    raise RuntimeError(
        f"数据导出的分钟边界容差预期为59秒，实际为{tolerance_seconds}秒；停止复核"
    )
if any(
    open_abs > tolerance_seconds or close_abs > tolerance_seconds
    for _, _, open_abs, close_abs, _ in nearest_pairs
):
    raise RuntimeError("存在超出派生容差的最近同品种候选")
selected_cycle_ids = [str(cycle["position_cycle_id"]) for _, cycle, *_ in nearest_pairs]
if len(set(selected_cycle_ids)) != 131:
    raise RuntimeError("T记录最近同品种候选不是一一唯一，需停止人工复核")

selected_by_t = {
    str(manual["manual_review_trade_id"]): {
        "manual": manual,
        "cycle": cycle,
        "open_abs": open_abs,
        "close_abs": close_abs,
        "runner_up_total": runner_up,
    }
    for manual, cycle, open_abs, close_abs, runner_up in nearest_pairs
}
selected_t_by_cycle = {
    str(item["cycle"]["position_cycle_id"]): t_id
    for t_id, item in selected_by_t.items()
}

unmatched_cycles = [
    cycle
    for cycle in cycles
    if str(cycle["position_cycle_id"]) not in selected_t_by_cycle
]
unmatched_cycles.sort(
    key=lambda cycle: (
        parse_time(cycle["cycle_start_time_utc"]),
        str(cycle["symbol"]),
        str(cycle["initial_direction"]),
        str(cycle["position_cycle_id"]),
    )
)
u_by_cycle = {
    str(cycle["position_cycle_id"]): f"U{index:03d}"
    for index, cycle in enumerate(unmatched_cycles, start=1)

if u_id:
    u_row = {
        "u_number": u_id,
        **{
            key: value
            for key, value in row.items()
            if key not in ("u_number",)
        },
        "u_generation_rule": (
            "周期开始UTC升序；同刻按symbol、direction、position_cycle_id"
        ),
    }
    u_rows.append(u_row)
if source["trading_origin"] == "COPY_TRADING":
    copy_rows.append(row)
else:
    personal_rows.append(row)

