    manual_close = parse_time(manual["manual_close_time_beijing"])
    candidates: list[tuple[float, float, float, dict[str, Any]]] = []
    for cycle in cycles:
        if str(cycle.get("symbol")) != manual_symbol:
            continue
        open_abs = abs(
            (
                parse_time(cycle["cycle_start_time_beijing"]) - manual_open
            ).total_seconds()
        )
        close_abs = abs(
            (
                parse_time(cycle["cycle_end_time_beijing"]) - manual_close
            ).total_seconds()
        )
        candidates.append((open_abs + close_abs, open_abs, close_abs, cycle))
    if not candidates:
        raise RuntimeError(
            f"{manual['manual_review_trade_id']}不存在同品种真实周期候选"
        )
    candidates.sort(
        key=lambda item: (
            item[0],
            item[3]["cycle_start_time_utc"],
            item[3]["position_cycle_id"],
        )
    )
    nearest = candidates[0]
    runner_up = candidates[1][0] if len(candidates) > 1 else None
    nearest_pairs.append(
        (manual, nearest[3], nearest[1], nearest[2], runner_up)
    )
tolerance_seconds = int(
    max(max(open_abs, close_abs) for _, _, open_abs, close_abs, _ in nearest_pairs)
