def source_classification(cycle: dict[str, Any]) -> dict[str, str | None]:
    is_copy = str(cycle.get("copy_trading_flag")).upper() == "TRUE"
    if is_copy:
        return {
            "trading_origin": "COPY_TRADING",
            "personal_or_copy": "自动跟单交易",
            "source_coverage": "BOTH_SOURCES_SAME_EVENT",
            "origin_confidence": "高",
            "origin_basis": (
                "阶段05_v2 account_origin=BOTH_SOURCES_SAME_EVENT；"
                "B01七字段逐Fill交叉覆盖；同一事件只计一次"
            ),
        }
    return {
        "trading_origin": "PERSONAL_ACTIVE",
        "personal_or_copy": "个人主动交易",
